const CODES = [200, 201, 204, 301, 302, 304, 400, 401, 403, 404, 429, 500, 502, 503, 504];

const CLASSES = {
  1: '信息（Informational）',
  2: '成功（Success）',
  3: '重定向（Redirection）',
  4: '客户端错误（Client Error）',
  5: '服务端错误（Server Error）',
};

// 可重试规则：408(请求超时) / 429(限流) / 5xx(服务端问题)；其余 4xx 重试无意义
const canRetry = (code) => code === 408 || code === 429 || code >= 500;

console.log('状态码 | 类别 | 可重试');
for (const c of CODES) {
  console.log(c + ' → ' + CLASSES[Math.floor(c / 100)] + ' | 可重试: ' + (canRetry(c) ? '是' : '否'));
}
console.log('');
console.log('要点：状态码首位定类（1信息/2成功/3重定向/4客户端错/5服务端错）。');
console.log('      4xx 是「调用方的问题」，重试无意义（除 408/429）；5xx 是「服务端的问题」，幂等时可重试。');
console.log('      监控告警通常只看 5xx —— 所以把错误塞进 200 会让告警失效。');
